describe("Radar — loading", () => {
  it("shows a placeholder in each tile, not a zero, while the first read is pending", async () => {
    const never = new Promise<unknown>(() => undefined);
    renderRadar(stubClient(() => never));
    for (const k of ["action", "open", "new", "resolved"]) {
      const tile = screen.getByTestId(`radar-kpi-${k}`);
      expect(tile.textContent).not.toBe("0");
      expect(tile.querySelector(".ops-skel")).not.toBeNull();
    }
  });
});

